<?php
namespace App\Console\Commands; use App\Services\Warehouse\Purchasing\WarehousePurchasingFinanceService; use Illuminate\Console\Command; use Illuminate\Support\Facades\DB;
class WarehousePurchasingBackfillInvoicesCommand extends Command{protected $signature='warehouse:purchasing-backfill-invoices {--limit=500}';protected $description='Membentuk Purchase Invoice untuk Stock In approved yang belum memiliki invoice';public function handle(WarehousePurchasingFinanceService $s):int{$user=DB::table('users')->first();if(!$user){$this->error('User tidak tersedia.');return self::FAILURE;}$rows=DB::table('wh_stock_ins as si')->leftJoin('wh_supplier_invoices as i','i.stock_in_id','=','si.id')->where('si.status','approved')->whereNull('i.id')->limit((int)$this->option('limit'))->pluck('si.id');foreach($rows as $id)$s->generateInvoice($id,$user);$this->info($rows->count().' invoice dibuat.');return self::SUCCESS;}}
